-- PostGIS Spatial Index Creation Script
-- Generated by audit_spatial_queries.py
-- Run this script against the database to create missing spatial indexes

-- Enable timing to measure index creation
\timing on

-- Set work_mem for faster index creation (adjust based on available memory)
SET work_mem = '256MB';

-- ============================================================================
-- Spatial Indexes for Main Tables
-- ============================================================================

-- Features table (common spatial queries)
CREATE INDEX IF NOT EXISTS features_geom_gist_idx
ON features
USING GIST (geom);

ANALYZE features;

-- ============================================================================
-- Spatial Indexes for Analysis Tables
-- ============================================================================

-- Final analysis results
CREATE INDEX IF NOT EXISTS final_geom_gist_idx
ON final
USING GIST (geom);

ANALYZE final;

-- Flood zones layer
CREATE INDEX IF NOT EXISTS flood_zones_geom_gist_idx
ON flood_zones
USING GIST (geom);

ANALYZE flood_zones;

-- Access levels
CREATE INDEX IF NOT EXISTS levels_geom_gist_idx
ON levels
USING GIST (geom);

ANALYZE levels;

