-- ============================================================================
-- Dataset-Specific Indexes (Cape Town GeoHub)
-- ============================================================================

-- Informal settlements
CREATE INDEX IF NOT EXISTS informal_settlements_geom_gist_idx
ON informal_settlements
USING GIST (geom)
WHERE geom IS NOT NULL;

ANALYZE informal_settlements;

-- MyCiTi stops
CREATE INDEX IF NOT EXISTS myciti_stops_geom_gist_idx
ON myciti_stops
USING GIST (geom)
WHERE geom IS NOT NULL;

ANALYZE myciti_stops;

-- MyCiTi routes
CREATE INDEX IF NOT EXISTS myciti_routes_geom_gist_idx
ON myciti_routes
USING GIST (geom)
WHERE geom IS NOT NULL;

ANALYZE myciti_routes;

-- Safety precincts
CREATE INDEX IF NOT EXISTS safety_precincts_geom_gist_idx
ON safety_precincts
USING GIST (geom)
WHERE geom IS NOT NULL;

ANALYZE safety_precincts;

-- Zoning
CREATE INDEX IF NOT EXISTS zoning_geom_gist_idx
ON zoning
USING GIST (geom)
WHERE geom IS NOT NULL;

ANALYZE zoning;

-- ============================================================================
-- Verify Index Creation
-- ============================================================================

-- Show all spatial indexes created
SELECT
    schemaname,
    tablename,
    indexname,
    pg_size_pretty(pg_relation_size(indexname::regclass)) as size
FROM pg_indexes
WHERE indexdef LIKE '%GIST%'
ORDER BY tablename, indexname;

-- Show index usage statistics
SELECT
    schemaname,
    tablename,
    indexname,
    idx_scan as scans,
    idx_tup_read as tuples_read,
    idx_tup_fetch as tuples_fetched
FROM pg_stat_user_indexes
WHERE indexname LIKE '%gist%'
ORDER BY idx_scan DESC;

-- ============================================================================
-- Performance Recommendations
-- ============================================================================

/*
After creating indexes:

1. Monitor query performance:
   - Use EXPLAIN ANALYZE to verify index usage
   - Check pg_stat_user_indexes for index scan counts
   - Monitor slow query logs

2. Maintain indexes:
   - Run VACUUM ANALYZE regularly
   - REINDEX if indexes become bloated
   - Monitor index size growth

3. Tune PostgreSQL settings:
   - shared_buffers (25% of RAM)
   - effective_cache_size (50-75% of RAM)
   - work_mem (for large sorts/aggregations)
   - maintenance_work_mem (for VACUUM, CREATE INDEX)

4. Use the benchmark API:
   POST /api/benchmark/analyze-spatial
   {
     "table_name": "informal_settlements",
     "geometry_column": "geom",
     "test_lon": 18.4241,
     "test_lat": -33.9249,
     "radius_meters": 1000
   }

5. Common PostGIS optimization patterns:
   - Use ST_DWithin instead of ST_Distance < value
   - Use geography type for accurate distance calculations
   - Use ST_Simplify to reduce geometry complexity
   - Add LIMIT clauses to prevent large result sets
   - Cache expensive calculations
*/

-- Reset work_mem
RESET work_mem;

\echo 'Spatial indexes created successfully!'
\echo 'Run ANALYZE on your database to update statistics.'
